1	import type { WorksheetRow } from '../lib/tableau';
2	
3	export interface TaskItem {
4	  text: string;
5	}
6	
7	type DataLoadState = 'idle' | 'loading' | 'done' | 'error';
8	
9	/**
10	 * Extracts the consultant's available open days from Tableau worksheet rows.
11	 * Looks for a column whose name contains "open" (case-insensitive) in the first row.
12	 * Returns null if the column is absent, the value is non-numeric, or rows are empty.
13	 * Column naming convention: "Open Days", "open_days", "Available Days", etc.
14	 */
15	export function extractAvailableDays(rows: WorksheetRow[]): number | null {
16	  if (rows.length === 0) return null;
17	  const row = rows[0];
18	  const key = Object.keys(row).find((k) => k.toLowerCase().includes('open'));
19	  if (!key) return null;
20	  const val = parseFloat(row[key]);
21	  return isNaN(val) ? null : val;
22	}
23	
24	class DataStore {
25	  // Tableau worksheet panel
26	  worksheetRows = $state<WorksheetRow[]>([]);
27	  worksheetState = $state<DataLoadState>('idle');
28	  worksheetError = $state<string | null>(null);
29	
30	  // Consultant's available open days — extracted from worksheetRows on load.
31	  // null when Tableau data is unavailable (triggers graceful capacity check failure).
32	  availableDays = $state<number | null>(null);
33	
34	  // Google Docs task list panel
35	  tasks = $state<TaskItem[]>([]);
36	  tasksState = $state<DataLoadState>('idle');
37	  tasksError = $state<string | null>(null);
38	}
39	
40	export const dataStore = new DataStore();
