1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { apiFetch, ApiError } from '../lib/api';
4	  import { getWorksheetData } from '../lib/tableau';
5	  import { sessionStore } from '../stores/session.svelte';
6	  import { dataStore, extractAvailableDays } from '../stores/data.svelte';
7	
8	  const sessionHeaders = (): Record<string, string> =>
9	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
10	
11	  // Returns worksheet name from config, or null if not set.
12	  // Throws ApiError/Error if the config endpoint is unreachable.
13	  async function loadWorksheetConfig(): Promise<string | null> {
14	    const config = await apiFetch<{ data: { data_panel?: { worksheet_name?: string } } | null }>(
15	      '/api/config/workflow'
16	    );
17	    return config.data?.data_panel?.worksheet_name ?? null;
18	  }
19	
20	  async function loadWorksheetData(worksheetName: string): Promise<void> {
21	    dataStore.worksheetState = 'loading';
22	    try {
23	      dataStore.worksheetRows = await getWorksheetData(worksheetName);
24	      dataStore.availableDays = extractAvailableDays(dataStore.worksheetRows);
25	      dataStore.worksheetState = 'done';
26	    } catch {
27	      // Generic message — never expose raw error details to the consultant (AC4)
28	      dataStore.worksheetError = 'Could not load worksheet data';
29	      dataStore.worksheetState = 'error';
30	    }
31	  }
32	
33	  async function loadTasks(): Promise<void> {
34	    dataStore.tasksState = 'loading';
35	    try {
36	      const response = await apiFetch<{ data: Array<{ text: string }> }>('/api/data/tasks', {
37	        headers: sessionHeaders(),
38	      });
39	      dataStore.tasks = response.data;
40	      dataStore.tasksState = 'done';
41	    } catch (err) {
42	      const msg =
43	        err instanceof ApiError
44	          ? err.message
45	          : err instanceof Error
46	            ? err.message
47	            : 'Could not load task list';
48	      dataStore.tasksError = msg;
49	      dataStore.tasksState = 'error';
50	    }
51	  }
52	
53	  onMount(() => {
54	    let active = true; // abort guard — prevents stale promise writes on rapid remount
55	
56	    (async () => {
57	      // Distinguish config fetch failure from worksheet simply not being configured
58	      let worksheetName: string | null = null;
59	      let configFetchError: string | null = null;
60	      try {
61	        worksheetName = await loadWorksheetConfig();
62	      } catch (err) {
63	        configFetchError =
64	          err instanceof ApiError ? err.message : 'Could not load configuration';
65	      }
66	
67	      if (!active) return;
68	
69	      // Both fetches run independently — one failure must not block the other (NFR9)
70	      const worksheetPromise = worksheetName
71	        ? loadWorksheetData(worksheetName)
72	        : (() => {
73	            dataStore.worksheetError = configFetchError ?? 'Worksheet name not configured';
74	            dataStore.worksheetState = 'error';
75	            return Promise.resolve();
76	          })();
77	
78	      await Promise.allSettled([worksheetPromise, loadTasks()]);
79	    })();
80	
81	    return () => {
82	      active = false; // cancel on unmount
83	    };
84	  });
85	</script>
