87	<div class="data-panel">
88	  <!-- Open days / scheduled engagements from Tableau worksheet -->
89	  <section class="panel-section">
90	    <h3>Open Days &amp; Engagements</h3>
91	    {#if dataStore.worksheetState === 'loading'}
92	      <p class="loading">Loading…</p>
93	    {:else if dataStore.worksheetState === 'error'}
94	      <p class="error">{dataStore.worksheetError}</p>
95	    {:else if dataStore.worksheetRows.length === 0}
96	      <p class="empty">No data available</p>
97	    {:else}
98	      <table>
99	        <thead>
100	          <tr>
101	            {#each Object.keys(dataStore.worksheetRows[0]) as col}
102	              <th>{col}</th>
103	            {/each}
104	          </tr>
105	        </thead>
106	        <tbody>
107	          {#each dataStore.worksheetRows as row}
108	            <tr>
109	              {#each Object.values(row) as val}
110	                <td>{val}</td>
111	              {/each}
112	            </tr>
113	          {/each}
114	        </tbody>
115	      </table>
116	    {/if}
117	  </section>
118	
119	  <!-- Task list from Google Docs -->
120	  <section class="panel-section">
121	    <h3>Task List</h3>
122	    {#if dataStore.tasksState === 'loading'}
123	      <p class="loading">Loading…</p>
124	    {:else if dataStore.tasksState === 'error'}
125	      <p class="error">{dataStore.tasksError}</p>
126	    {:else if dataStore.tasks.length === 0}
127	      <p class="empty">No tasks available</p>
128	    {:else}
129	      <ul>
130	        {#each dataStore.tasks as task}
131	          <li>{task.text}</li>
132	        {/each}
133	      </ul>
134	    {/if}
135	  </section>
136	</div>
