1	<script lang="ts">
2	  import { apiFetch, ApiError } from '../lib/api';
3	  import { sessionStore } from '../stores/session.svelte';
4	  import { chatStore } from '../stores/chat.svelte';
5	  import { dataStore } from '../stores/data.svelte';
6	  import type { ToolCallProposal } from '../stores/chat.svelte';
7	  import MessageList from './MessageList.svelte';
8	  import InputBar from './InputBar.svelte';
9	  import ActionConfirm from './ActionConfirm.svelte';
10	
11	  const sessionHeaders = (): Record<string, string> =>
12	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
13	
14	  /**
15	   * Build session_context from dataStore for the masking pipeline (FR17).
16	   * Sends all non-empty worksheet column values as identifiable fields.
17	   * Field name determines the masking category: fields containing "consultant",
18	   * "client", or "engagement" get typed tokens; others get VALUE_ prefix.
19	   */
20	  function buildSessionContext(): Record<string, string> {
21	    const ctx: Record<string, string> = {};
22	    if (dataStore.worksheetRows.length > 0) {
23	      const firstRow = dataStore.worksheetRows[0];
24	      for (const [key, val] of Object.entries(firstRow)) {
25	        if (val && typeof val === 'string' && val.trim()) {
26	          ctx[key] = val;
27	        }
28	      }
29	    }
30	    return ctx;
31	  }
32	
33	  async function sendMessage(message: string): Promise<void> {
34	    chatStore.clearError();
35	    chatStore.clearPendingAction();
36	    chatStore.addUserMessage(message);
37	    chatStore.chatState = 'loading';
38	
39	    try {
40	      const body = {
41	        message,
42	        history: chatStore.history.slice(0, -1), // all turns before the one just added
43	        session_context: buildSessionContext(),
44	        available_days: dataStore.availableDays,
45	      };
46	
47	      type ChatApiResponse = {
48	        data: { reply: string | null; pending_action: ToolCallProposal | null };
49	        meta: { request_id: string };
50	      };
51	
52	      const response = await apiFetch<ChatApiResponse>('/api/chat', {
53	        method: 'POST',
54	        headers: sessionHeaders(),
55	        body: JSON.stringify(body),
56	      });
57	
58	      // If LLM returned explanatory text alongside the tool call, add it to the chat.
59	      if (response.data.reply) {
60	        chatStore.addAssistantMessage(response.data.reply);
61	      }
62	
63	      if (response.data.pending_action) {
64	        chatStore.setPendingAction(response.data.pending_action);
65	      }
66	
67	      chatStore.chatState = 'idle';
68	    } catch (err) {
69	      const msg =
70	        err instanceof ApiError
71	          ? err.message
72	          : err instanceof Error
73	            ? err.message
74	            : 'Something went wrong. Please try again.';
75	      chatStore.setError(msg);
76	    }
77	  }
78	
79	  async function confirmAction(): Promise<void> {
80	    const action = chatStore.pendingAction;
81	    if (!action) return;
82	
83	    chatStore.chatState = 'loading';
84	
85	    try {
86	      type ChatApiResponse = {
87	        data: { reply: string | null; pending_action: ToolCallProposal | null };
88	      };
89	
90	      const response = await apiFetch<ChatApiResponse>('/api/chat', {
91	        method: 'POST',
92	        headers: sessionHeaders(),
93	        body: JSON.stringify({
94	          confirm_action: {
95	            tool_name: action.tool_name,
96	            action: action.action,
97	            params: action.params,
98	          },
99	          history: chatStore.history,
100	          session_context: buildSessionContext(),
101	        }),
102	      });
103	
104	      chatStore.clearPendingAction();
105	      chatStore.addAssistantMessage(response.data.reply ?? 'Done.');
106	      chatStore.chatState = 'idle';
107	    } catch (err) {
108	      const msg =
109	        err instanceof ApiError
110	          ? err.message
111	          : err instanceof Error
112	            ? err.message
113	            : 'Could not complete the action. Please try again.';
114	      chatStore.setError(msg);
115	    }
116	  }
117	
118	  function cancelAction(): void {
119	    chatStore.clearPendingAction();
120	    chatStore.addAssistantMessage('Action cancelled. How else can I help?');
121	    chatStore.chatState = 'idle';
122	  }
123	</script>
124	
125	<div class="chat-panel">
126	  <h3>Chat</h3>
127	  <div class="chat-body">
128	    <MessageList messages={chatStore.messages} />
129	    {#if chatStore.chatState === 'error'}
130	      <p class="error">{chatStore.chatError}</p>
131	    {/if}
132	    {#if chatStore.pendingAction}
133	      <ActionConfirm
134	        action={chatStore.pendingAction}
135	        onConfirm={confirmAction}
136	        onCancel={cancelAction}
137	      />
138	    {/if}
139	  </div>
140	  <InputBar
141	    onSend={sendMessage}
142	    disabled={chatStore.chatState === 'loading' || chatStore.pendingAction !== null}
143	  />
144	</div>
145	
146	<style>
147	  .chat-panel {
148	    display: flex;
149	    flex-direction: column;
150	    height: 100%;
151	    font-family: sans-serif;
152	  }
153	  h3 {
154	    font-size: 0.875rem;
155	    font-weight: 600;
156	    margin: 0;
157	    padding: 0.75rem 0.75rem 0.5rem;
158	    text-transform: uppercase;
159	    letter-spacing: 0.05em;
160	    color: #444;
161	    border-bottom: 1px solid #eee;
162	  }
163	  .chat-body {
164	    flex: 1;
165	    display: flex;
166	    flex-direction: column;
167	    overflow: hidden;
168	  }
